try{const saved=JSON.parse(localStorage.getItem('mingo-destinations')||'null');if(saved?.provinces?.length===34&&saved.images){window.PROVINCES=saved.provinces;window.IMAGE_MAP=saved.images}}catch{}
let adminLoaded=false,adminScriptPromise=null;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), money=n=>new Intl.NumberFormat('vi-VN').format(n)+' ₫';
const seed=[['halong','Quảng Ninh','Hạ Long — một khoảng trời xanh','Vịnh Hạ Long',3290000,3],['trangan','Ninh Bình','Ninh Bình — giữa miền di sản','Tràng An',1890000,2],['hoian','Đà Nẵng','Đà Nẵng & Hội An — nắng bên hiên','Phố cổ Hội An',4590000,4],['dalat','Lâm Đồng','Đà Lạt — chậm một nhịp giữa thông','Đà Lạt',2890000,3],['sapa','Lào Cai','Sa Pa — qua những mùa mây','Sa Pa',3590000,3],['phuquoc','An Giang','Phú Quốc — hẹn với biển xanh','Phú Quốc',5290000,4]];
let tours=JSON.parse(localStorage.getItem('dv-tours')||'null')||seed.map((t,i)=>({id:t[0],province:t[1],title:t[2],place:t[3],price:t[4],days:t[5],capacity:24,hidden:false,dates:['2026-12-05','2026-12-12','2026-12-19'],desc:['Lênh đênh giữa những đảo đá, dành một buổi chiều thong thả ngắm vịnh và thưởng thức hải sản.','Đi thuyền qua những dãy núi đá vôi, ghé cố đô Hoa Lư và khám phá hương vị đất Ninh Bình.','Một hành trình nối biển Đà Nẵng với những con phố nhỏ Hội An, đủ thời gian để ngắm, ăn và dạo bước.','Dành những ngày mát lành cho đồi thông, hồ nước và những bữa ăn nóng hổi giữa phố núi.','Ghé bản làng, đi qua ruộng bậc thang và dành thời gian cho những cung đường quanh Sa Pa.','Thư thả bên bờ biển, dạo chợ và khám phá những món ăn quen thuộc của đảo ngọc.'][i]}));

const tourDefaults=tours.slice();
for(const p of PROVINCES){if(!tours.some(t=>t.province===p.name)){tours.push({id:'province-'+p.id,province:p.name,title:p.name+' — khám phá '+p.attractions[0],place:p.attractions[0],price:1890000+(p.id%5)*300000,days:3,capacity:24,hidden:false,dates:['2026-12-05','2026-12-12','2026-12-19'],desc:'Hành trình 3 ngày tại '+p.name+', tập trung khám phá '+p.attractions[0]+', tìm hiểu đời sống địa phương và thưởng thức những món ăn đặc trưng.'})}}
for(const t of tours){if(!IMAGE_MAP[t.place]){let p=province(t.province);let n=p.attractions.find(n=>IMAGE_MAP[n]);if(n)t.place=n}}
let bookings=JSON.parse(localStorage.getItem('dv-bookings')||'[]'),user=null,adminTab='overview',region='Tất cả';
function save(){localStorage.setItem('dv-tours',JSON.stringify(tours));localStorage.setItem('dv-bookings',JSON.stringify(bookings))}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}function province(name){return PROVINCES.find(p=>p.name===name)||PROVINCES[0]}
function image(name,cls=''){let m=window.IMAGE_MAP?.[name];return m?`<img class="${cls}" src="${esc(m.url)}" alt="${esc(name)}" loading="lazy"><small class="source">Nguồn ảnh: ${esc(m.source)}</small>`:`<div class="placeholder">${esc(name)} · Đang bổ sung ảnh</div>`}
function photo(name){let m=window.IMAGE_MAP?.[name];return m?`<img src="${esc(m.url)}" alt="${esc(name)}" loading="lazy">`:`<div class="placeholder">${esc(name)}</div>`}
function card(t){const p=province(t.province),departure=t.dates[0],seats=remaining(t,departure);return `<article class="tour-card" onmouseenter="positionTourPreview(this)" onfocusin="positionTourPreview(this)"><a href="#tour/${esc(t.id)}" class="tour"><div class="photo">${photo(t.place)}<span class="badge">${t.days} NGÀY ${t.days-1} ĐÊM</span></div><small class="source">${IMAGE_MAP?.[t.place]?'Nguồn ảnh: '+esc(IMAGE_MAP[t.place].source):'Đang bổ sung ảnh'}</small><p class="sub">${esc(t.province)}</p><h3>${esc(t.title)}</h3><small>${t.dates.length} ngày khởi hành · Còn ${Math.max(0,seats)} chỗ</small><div class="bottom"><div><small>Từ </small><span class="price">${money(t.price)}</span><small> / khách</small></div><span class="arrow">→</span></div><div class="tour-preview" id="preview-${esc(t.id)}"><span class="preview-kicker">XEM NHANH HÀNH TRÌNH</span><dl><div><dt>Ghé thăm</dt><dd>${esc(t.place)}</dd></div><div><dt>Hương vị địa phương</dt><dd>${esc(p.specialties.slice(0,2).join(' · '))}</dd></div><div class="preview-schedule"><div><dt>Khởi hành</dt><dd>${date(departure)}</dd></div><div><dt>Chỗ còn lại</dt><dd>${Math.max(0,seats)} khách</dd></div></div></dl><span class="preview-action">Xem lịch trình chi tiết &nbsp; →</span></div></a><button type="button" class="tour-preview-toggle" aria-label="Xem nhanh ${esc(t.title)}" aria-controls="preview-${esc(t.id)}" aria-expanded="false" onclick="positionTourPreview(this.closest('.tour-card'));const opened=this.closest('.tour-card').classList.toggle('is-preview');positionTourPreview(this.closest('.tour-card'));this.setAttribute('aria-expanded',String(opened));this.textContent=opened?'Đóng':'Xem nhanh'">Xem nhanh</button></article>`}

function date(d){return d.split('-').reverse().join('/')}function options(){return ['Miền Bắc','Miền Trung','Miền Nam'].map(name=>`<option value="${name}">${name}</option>`).join('')}
function priceOptions(){return '<option value="0">Tất cả mức giá</option>'+[1,2,3,4].map(n=>`<option value="${n}">${new Intl.NumberFormat('vi-VN').format(n*1000000)} – ${new Intl.NumberFormat('vi-VN').format((n+1)*1000000-1)} VND</option>`).join('')+'<option value="5">Trên 5.000.000 VND</option>'}
function matchesPrice(price,band){return !band||(band===5?price>=5000000:price>=band*1000000&&price<(band+1)*1000000)}

function home(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">VIỆT NAM, THEO CÁCH CỦA BẠN</div><h1>Đi để hiểu.<br>Đến để thương.</h1><p>Từ miền núi đón mây đến những con phố bên sông. Chọn một nơi, dành vài ngày và mang về một câu chuyện.</p><a href="#tours"><button>Tìm chuyến đi của bạn &nbsp; →</button></a></div><div class="hero-photo"><img src="/images/trang-an-hero-hd.jpg" alt="Tràng An, Ninh Bình" fetchpriority="high" decoding="async"><div class="hero-tag">20°15′B · 105°55′Đ<b>Một chiều ở Tràng An</b>Ninh Bình, Việt Nam</div><small class="source">Nguồn ảnh: Wikimedia Commons</small></div></section><form class="searchbar" onsubmit="searchHome(event)"><label>Bạn muốn đi miền nào?<select id="home-province"><option value="">Tất cả</option>${options()}</select></label><label>Khoảng giá<select id="home-price">${priceOptions()}</select></label><label>Thời gian<select id="home-days"><option value="0">Mọi thời lượng</option><option value="2">2 ngày</option><option value="3">3 ngày</option><option value="4">4 ngày</option></select></label><button>Tìm tour →</button></form><section class="wrap"><div class="section-head"><div><div class="eyebrow">GỢI Ý CHO CHUYẾN ĐI TỚI</div><h2>Những hành trình đáng đi</h2></div><a class="textlink" href="#tours">Xem tất cả tour →</a></div><div class="grid">${tours.filter(t=>!t.hidden).slice(0,6).map(card).join('')}</div></section><section class="editorial"><div><div class="eyebrow">ĐI MỘT NƠI, NHỚ MỘT VỊ</div><h2>Có những miền đất<br>được nhớ bằng món ăn.</h2><p>Một bát cao lầu giữa phố Hội, một món bánh nóng trong buổi sáng se lạnh. Mỗi chuyến đi đều có những hương vị để bạn tìm hiểu.</p><a class="textlink" href="#places">Khám phá địa danh & đặc sản →</a></div><div class="photos"><figure>${image('Cao lầu Hội An')}<figcaption>Cao lầu · Hội An</figcaption></figure><figure>${image('Phố cổ Hội An')}<figcaption>Một góc phố Hội · Đà Nẵng</figcaption></figure></div></section><section class="wrap"><div class="section-head"><div><div class="eyebrow">BẢN ĐỒ CHUYẾN ĐI</div><h2>34 tỉnh thành. Vô vàn câu chuyện.</h2></div><a class="textlink" href="#places">Chọn điểm đến →</a></div><div class="province-grid">${PROVINCES.slice(0,12).map(provinceCard).join('')}</div></section>`}
function provinceCard(p){const code=p.plateLabel.match(/^\d+/)?.[0]||'';return `<a class="province" href="#province/${p.id}"><span class="province-name">${esc(p.name)}<small class="province-count">${tours.filter(t=>!t.hidden&&t.province===p.name).length} tour</small></span><span class="province-code" aria-label="Biển số xe: ${esc(code)}">${esc(code)}</span></a>`}
function searchHome(e){e.preventDefault();location.hash='tours?region='+encodeURIComponent($('#home-province').value)+'&price='+$('#home-price').value+'&days='+$('#home-days').value}
function catalog(q){return `<section class="wrap"><div class="eyebrow">CHỌN MỘT CHUYẾN ĐI</div><h1 style="font-size:48px">Đi đâu tiếp theo?</h1><p class="muted">34 hành trình mẫu cho 34 tỉnh, thành. Chọn nơi bạn muốn đến để khám phá.</p><div class="toolbar"><input id="q" placeholder="Tìm tên tour, điểm đến…" aria-label="Tìm tour" oninput="filterTours()"><select id="p" aria-label="Miền" onchange="filterTours()"><option value="">Tất cả</option>${options()}</select><select id="price" aria-label="Giá" onchange="filterTours()">${priceOptions()}</select><select id="days" aria-label="Số ngày" onchange="filterTours()"><option value="0">Mọi thời lượng</option><option value="2">2 ngày</option><option value="3">3 ngày</option><option value="4">4 ngày</option></select></div><div class="toolbar"><label>Khởi hành từ<input type="date" id="from-date" onchange="filterTours()"></label><label>Sắp xếp<select id="sort" onchange="filterTours()"><option value="default">Gợi ý</option><option value="price">Giá tăng dần</option><option value="price-desc">Giá giảm dần</option><option value="days">Thời lượng ngắn nhất</option><option value="date">Khởi hành sớm nhất</option></select></label></div><p id="count" class="muted"></p><div id="results" class="grid"></div></section>`}
function filterTours(){let q=$('#q').value.toLocaleLowerCase('vi'),p=$('#p').value,price=+$('#price').value,days=+$('#days').value;let a=tours.filter(t=>!t.hidden&&(!p||province(t.province).region===p)&&matchesPrice(t.price,price)&&(!days||t.days===days)&&(t.title+' '+t.province).toLocaleLowerCase('vi').includes(q));const from=$('#from-date')?.value;if(from)a=a.filter(t=>t.dates.some(d=>d>=from));const sort=$('#sort')?.value;a.sort((x,y)=>sort==='price'?x.price-y.price:sort==='price-desc'?y.price-x.price:sort==='days'?x.days-y.days:sort==='date'?(x.dates.filter(d=>!from||d>=from).sort()[0]||'').localeCompare(y.dates.filter(d=>!from||d>=from).sort()[0]||''):0);$('#count').textContent=a.length+' hành trình phù hợp';$('#results').innerHTML=a.length?a.map(card).join(''):'<div class="empty" style="grid-column:1/-1"><h3>Chưa có tour phù hợp</h3><p>Thử thay đổi bộ lọc, hoặc khám phá địa danh ở mục Điểm đến.</p><a class="textlink" href="#places">Khám phá điểm đến →</a></div>'}
function places(){return `<section class="wrap"><div class="eyebrow">ĐỊA DANH & ẨM THỰC</div><h1 style="font-size:48px">Việt Nam, từ Bắc vào Nam.</h1><p class="muted">Danh mục Điểm đến theo địa giới sau sắp xếp năm 2025.</p><div class="toolbar"><input id="place-q" placeholder="Tìm tỉnh thành…" oninput="filterPlaces()" aria-label="Tìm tỉnh thành"></div><div id="province-list" class="province-grid">${regionList(PROVINCES)}</div></section>`}function filterPlaces(){let q=$('#place-q').value.toLowerCase();$('#province-list').innerHTML=regionList(PROVINCES.filter(p=>p.name.toLowerCase().includes(q)))||'<p>Không tìm thấy tỉnh thành.</p>'}
function minis(list){return `<div class="mini-grid">${list.map(n=>`<article>${image(n)}<h3>${esc(n)}</h3><p>${esc(IMAGE_MAP[n]?.description||'Gợi ý khám phá trong hành trình tại địa phương. Xem lịch trình tour để biết các điểm dừng được bao gồm.')}</p></article>`).join('')}</div>`}
function provincePage(id){let p=PROVINCES.find(p=>String(p.id)===String(id));if(!p)return '<div class="wrap">Không tìm thấy điểm đến.</div>';let ts=tours.filter(t=>t.province===p.name&&!t.hidden);return `<section class="wrap"><div class="breadcrumb"><a href="#places">Điểm đến</a> / ${esc(p.name)}</div><div class="eyebrow">MỘT ĐIỂM ĐẾN, NHIỀU TRẢI NGHIỆM</div><h1>${esc(p.name)}</h1><p class="muted">${esc(p.name)} thuộc ${esc(p.region)}, với những điểm dừng như ${esc(p.attractions.slice(0,2).join(" và "))}. Khám phá cảnh sắc và thưởng thức ${esc(p.specialties[0])} trong chuyến đi của bạn.</p><a class="textlink" href="#" onclick="event.preventDefault();document.getElementById('province-tours').scrollIntoView({behavior:'smooth'})">Xem tour tại ${esc(p.name)} →</a><section class="detail-section"><h2>Những nơi nên ghé</h2>${minis(p.attractions)}</section><section class="detail-section"><h2>Đặc sản nên thử</h2><p class="notice">Gợi ý thưởng thức, không mặc định bao gồm trong giá tour.</p>${minis(p.specialties)}</section><h2 id="province-tours" style="margin-bottom:25px">Tour đến ${esc(p.name)}</h2><div class="grid">${ts.length?ts.map(card).join(''):'<p class="muted">Lịch tour đang được xây dựng. Bạn có thể khám phá các địa danh và món ăn ở trên.</p>'}</div></section>`}
function remaining(t,d){return t.capacity-bookings.filter(b=>b.tourId===t.id&&b.date===d&&b.status!=='cancelled').reduce((s,b)=>s+b.people,0)}
function detail(id){let t=tours.find(t=>t.id===id&&!t.hidden);if(!t)return '<div class="wrap">Tour đã ngừng bán hoặc không tồn tại.</div>';let p=province(t.province);return `<section class="wrap"><div class="breadcrumb"><a href="#tours">Lữ trình</a> / ${esc(t.province)}</div><div class="eyebrow">${t.days} NGÀY ${t.days-1} ĐÊM · ${esc(t.province)}</div><h1 class="detail-title">${esc(t.title)}</h1><div class="detail-photo">${photo(t.place)}</div><small class="source">Nguồn ảnh: ${esc(IMAGE_MAP?.[t.place]?.source||'Đang bổ sung')}</small><div class="tabs"><a href="#" onclick="event.preventDefault();$('#overview').scrollIntoView()">Tổng quan</a><a href="#" onclick="event.preventDefault();$('#attractions').scrollIntoView()">Địa danh</a><a href="#" onclick="event.preventDefault();$('#food').scrollIntoView()">Đặc sản</a><a href="#" onclick="event.preventDefault();$('#itinerary').scrollIntoView()">Lịch trình</a></div><div class="detail-layout"><div><section id="overview" class="detail-section"><h2>Một chuyến đi vừa vặn</h2><p>${esc(t.desc)}</p><p class="notice">Đón tại điểm hẹn trong tỉnh. Giá và lịch trình mẫu phục vụ đồ án, chưa bao gồm vé máy bay đến điểm đón. Các địa danh giới thiệu bên dưới không mặc định đều nằm trong lịch trình.</p><p class="notice">Lịch trình và giá là dữ liệu mẫu phục vụ đồ án; chưa phải dịch vụ được mở bán thực tế.</p></section><section id="attractions" class="detail-section"><h2>Địa danh nổi bật tại điểm đến</h2>${minis(p.attractions)}</section><section id="food" class="detail-section"><h2>Hương vị của ${esc(t.province)}</h2><p class="notice">Gợi ý thưởng thức · Chi phí ăn uống tự túc.</p>${minis(p.specialties)}</section><section id="itinerary" class="detail-section"><h2>Lịch trình dự kiến</h2>${Array.from({length:t.days},(_,i)=>`<div class="day"><strong>NGÀY ${i+1}</strong><div><h3>${esc(i===0?'Đến '+t.province:i===t.days-1?'Tạm biệt '+t.province:t.place)}</h3><p>${esc(i===0?'Đón đoàn tại điểm hẹn trong tỉnh, nhận phòng và dạo khu vực trung tâm.':i===t.days-1?'Ăn sáng, tự do mua đặc sản địa phương, trả phòng và kết thúc hành trình.':'Dành ngày tham quan '+t.place+', nghỉ ngơi và trải nghiệm ẩm thực địa phương.')}</p></div></div>`).join('')}</section></div><aside class="booking-panel"><div class="eyebrow">ĐẶT CHUYẾN ĐI</div><span class="price">${money(t.price)}</span><small> / khách</small><form onsubmit="book(event,'${t.id}')"><label>Ngày khởi hành<select id="departure" onchange="quote('${t.id}')">${t.dates.map(d=>`<option value="${d}">${date(d)} — ${remaining(t,d)} chỗ</option>`).join('')}</select></label><label>Số khách<input type="number" id="people" min="1" max="${t.capacity}" value="1" required oninput="quote('${t.id}')"></label><label>Họ tên người đại diện<input name="name" required maxlength="80" value="${esc(user?.name||'')}" autocomplete="name"></label><label>Số điện thoại<input name="phone" type="tel" value="${esc(user?.phone||'')}" required pattern="[0-9+ ()-]{9,16}" autocomplete="tel"></label><div class="total"><span>Tổng tiền</span><b id="quote">${money(t.price)}</b></div><button>Đặt tour &nbsp; →</button><p class="notice">Đơn chờ xác nhận sẽ giữ chỗ. Bạn có thể hủy trước khi Admin xác nhận.</p></form></aside></div></section>`}
function quote(id){let t=tours.find(t=>t.id===id);$('#quote').textContent=money(t.price*(+$('#people').value||0))}function book(e,id){e.preventDefault();if(!user){account();toast('Vui lòng đăng nhập để đặt tour.');return}if(user.role==='admin'){toast('Vui lòng dùng tài khoản khách hàng để đặt tour.');return}let t=tours.find(t=>t.id===id),n=+$('#people').value,d=$('#departure').value;if(!Number.isInteger(n)||n<1||n>remaining(t,d))return toast('Số khách vượt số chỗ còn lại.');let f=new FormData(e.target);bookings.unshift({id:'DV'+Date.now().toString().slice(-8),tourId:id,title:t.title,date:d,people:n,unitPrice:t.price,total:n*t.price,name:f.get('name'),phone:f.get('phone'),userId:user.id,status:'pending',paid:false});save();toast('Đã tạo đơn đặt tour.');location.hash='bookings'}
function account(){if(user){if(user.role==='admin'){location.hash='admin';return}location.hash='profile';return}modal(authForm())}
function authForm(register=false){return `<h2>${register?'Tạo tài khoản':'Đăng nhập'}</h2><form class="form" onsubmit="${register?'registerAccount':'login'}(event)">${register?'<label>Họ tên<input name="name" autocomplete="name" maxlength="80" required></label>':''}<label>Tên đăng nhập<input name="username" autocomplete="username" required minlength="3" maxlength="32" pattern="[A-Za-z0-9_]+"></label><label>Mật khẩu<input name="password" type="password" autocomplete="${register?'new-password':'current-password'}" required ${register?'minlength="6"':''} maxlength="128"></label><p id="auth-error" role="alert" style="color:var(--orange)"></p><button>${register?'Đăng ký':'Đăng nhập'}</button></form><p style="text-align:center;margin-bottom:0">${register?'Đã có tài khoản?':'Chưa có tài khoản?'} <button class="auth-link" onclick="$('#modal-body').innerHTML=authForm(${!register})">${register?'Đăng nhập':'Đăng ký'}</button></p>`}
async function authSubmit(e,path){e.preventDefault();let button=e.target.querySelector('button');button.disabled=true;try{let r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))}),data=await r.json();if(!r.ok){$('#auth-error').textContent=data.error||'Không thể thực hiện. Vui lòng thử lại.';return null}return data}catch{$('#auth-error').textContent='Không thể kết nối. Vui lòng thử lại.';return null}finally{button.disabled=false}}
async function login(e){let data=await authSubmit(e,'/api/auth/login');if(!data)return;user=data.user;$('#modal').close();if(user.role==='admin'){location.hash='admin';render()}else render();toast('Đăng nhập thành công.')}
async function registerAccount(e){let data=await authSubmit(e,'/api/auth/register');if(!data)return;$('#modal-body').innerHTML=authForm();toast('Đăng ký thành công. Bạn có thể đăng nhập ngay.')}
async function logout(){try{let r=await fetch('/api/auth/logout',{method:'POST'});if(!r.ok)throw Error();user=null;sessionStorage.removeItem('dv-user');location.hash='home';render();toast('Đã đăng xuất.')}catch{toast('Chưa thể đăng xuất. Vui lòng thử lại.')}}
function profilePage(){if(!user||user.role!=='customer')return '<section class="wrap"><h2>Thông tin cá nhân</h2><p>Vui lòng đăng nhập tài khoản khách hàng.</p><button onclick="account()">Đăng nhập</button></section>';return `<section class="wrap" style="max-width:700px"><div class="eyebrow">TÀI KHOẢN CỦA BẠN</div><div class="section-head"><h1 style="font-size:40px">Thông tin cá nhân</h1><button class="outline" onclick="logout()">Đăng xuất</button></div><p class="muted">Tên đăng nhập: <b>${esc(user.username)}</b></p><form class="form" onsubmit="saveProfile(event)"><label>Họ tên<input name="name" value="${esc(user.name)}" maxlength="80" required autocomplete="name"></label><label>Email (không bắt buộc)<input name="email" type="email" value="${esc(user.email)}" maxlength="120" autocomplete="email"></label><label>Số điện thoại (không bắt buộc)<input name="phone" type="tel" value="${esc(user.phone)}" maxlength="20" autocomplete="tel"></label><label>Ngày sinh (không bắt buộc)<input name="birthday" type="date" value="${esc(user.birthday)}"></label><label>Địa chỉ (không bắt buộc)<textarea name="address" maxlength="250" autocomplete="street-address">${esc(user.address)}</textarea></label><p id="profile-error" role="alert" style="color:var(--orange)"></p><button>Lưu thông tin</button></form></section>`}
async function saveProfile(e){e.preventDefault();let b=e.target.querySelector('button');b.disabled=true;try{let r=await fetch('/api/profile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))}),data=await r.json();if(!r.ok){$('#profile-error').textContent=data.error;return}user=data.user;render();toast('Đã lưu thông tin cá nhân.')}catch{$('#profile-error').textContent='Không thể kết nối. Vui lòng thử lại.'}finally{b.disabled=false}}
async function restoreAccount(){try{let r=await fetch('/api/auth/me',{cache:'no-store'});if(r.ok){user=(await r.json()).user;render()}}catch{}}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal()}const statusName={pending:'Chờ xác nhận',confirmed:'Đã xác nhận',cancelled:'Đã hủy'};
function myBookings(){let a=user?bookings.filter(b=>b.userId===user.id):[];return `<section class="wrap"><div class="eyebrow">CHUYẾN ĐI CỦA BẠN</div><h1 style="font-size:48px">Những cuộc hẹn với Việt Nam</h1><p class="muted">Theo dõi lịch khởi hành và trạng thái đặt tour.</p>${!user?'<div class="empty"><h3>Đăng nhập để xem đơn</h3><p>Dùng tài khoản đã đặt tour trên trình duyệt này.</p><button onclick="account()">Đăng nhập</button></div>':!a.length?'<div class="empty"><h3>Chuyến đi đầu tiên đang chờ bạn.</h3><p>Chọn một hành trình để bắt đầu.</p><a href="#tours"><button>Tìm tour →</button></a></div>':a.map(b=>`<article class="booking-row"><div><small>${b.id} · ${date(b.date)}</small><h3>${esc(b.title)}</h3><span class="status ${b.status==='cancelled'?'cancel':''}">${statusName[b.status]}</span><p>${b.people} khách · ${b.paid?'Đã thanh toán':'Chưa thanh toán'}</p></div><div><b>${money(b.total)}</b><p>${esc(b.name)}</p>${b.status==='pending'?`<button class="outline" onclick="cancelBooking('${b.id}',false)">Hủy đơn</button>`:''}</div></article>`).join('')}</section>`}
function cancelBooking(id,admin){let b=bookings.find(b=>b.id===id);if(!admin&&(!user||b.userId!==user.id||b.status!=='pending'))return;if(b.paid)return toast('Đơn đã thu tiền: cần ghi nhận hoàn tiền trước khi hủy.');if(!confirm('Hủy đơn '+b.id+' và trả lại số chỗ?'))return;b.status='cancelled';save();render()}
function render(){const adminNav=document.querySelector('#admin-nav');if(adminNav)adminNav.hidden=user?.role!=='admin';let [path,query]=(location.hash.slice(1)||'home').split('?'),[page,id]=path.split('/');$('#account').textContent=user?user.name+' →':'Đăng nhập →';$('#app').innerHTML=page==='home'?home():page==='tours'?catalog(query):page==='places'?places():page==='province'?provincePage(id):page==='tour'?detail(id):page==='bookings'?myBookings():page==='admin'?adminLoading():page==='profile'?profilePage():home();if(page==='tours'){let q=new URLSearchParams(query);$('#p').value=q.get('region')||(PROVINCES.find(p=>p.name===q.get('province'))?.region)||'';$('#price').value=['1','2','3','4','5'].includes(q.get('price'))?q.get('price'):'0';$('#days').value=q.get('days')||'0';filterTours()}if(page==='admin')openAdmin();document.title=(page==='admin'?'Quản trị':page==='tour'?(tours.find(t=>t.id===id)?.title||'Tour'):'mingo — Đi để hiểu, đến để thương')+' | mingo'}window.addEventListener('hashchange',()=>{render();scrollTo(0,0)});render();


function adminLoading(){return '<section class="wrap"><p>Đang kiểm tra phiên quản trị…</p></section>'}
function adminLoginPage(error=''){return `<section class="wrap" style="max-width:520px"><div class="eyebrow">KHU VỰC QUẢN TRỊ</div><h1 style="font-size:38px">Đăng nhập</h1><p class="muted">Vui lòng đăng nhập bằng tài khoản quản trị.</p><p role="alert">${esc(error)}</p><button onclick="modal(authForm())">Đăng nhập</button></section>`}
async function openAdmin(){try{let r=await fetch('/api/admin/session',{cache:'no-store'});if(!r.ok)throw Error('network');let a=await r.json();if(!location.hash.startsWith('#admin'))return;if(!a.authenticated){$('#app').innerHTML=adminLoginPage();return}if(!adminLoaded){if(!adminScriptPromise)adminScriptPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='/admin.js?v=20261115';script.onload=resolve;script.onerror=()=>{script.remove();adminScriptPromise=null;reject(new Error('Không tải được giao diện quản trị'))};document.head.appendChild(script)});await adminScriptPromise;adminLoaded=true}if(location.hash.startsWith('#admin'))$('#app').innerHTML=admin()}catch(e){$('#app').innerHTML=adminLoginPage('Không thể kiểm tra phiên quản trị. Vui lòng thử lại.')}}
async function adminLogout(){await logout()}
restoreAccount();

function positionTourPreview(card){const panel=card.querySelector('.tour-preview');if(!panel)return;const rect=card.getBoundingClientRect(),scale=matchMedia('(hover:hover) and (pointer:fine)').matches?1.1:1,width=card.offsetWidth,center=rect.left+rect.width/2,left=center-width*scale/2,right=center+width*scale/2,spaceLeft=left-20,spaceRight=innerWidth-right-20,side=spaceRight>=300||spaceRight>=spaceLeft?'right':'left',space=Math.max(spaceLeft,spaceRight);card.dataset.previewSide=space<220?'inside':side;panel.style.setProperty('--preview-width',Math.min(320,Math.max(220,space-12))/scale+'px');const visualHeight=panel.offsetHeight*scale,top=Math.max(12,Math.min(rect.top,innerHeight-visualHeight-16));panel.style.setProperty('--preview-y',(top-rect.top)/scale+'px')}
window.addEventListener('resize',()=>{document.querySelectorAll('.tour-card:hover,.tour-card.is-preview,.tour-card:focus-within').forEach(positionTourPreview)});

function regionList(list){return ['Miền Bắc','Miền Trung','Miền Nam'].map(r=>{const ps=list.filter(p=>p.region===r);return ps.length?`<section class="region-block"><h2>${r}</h2><div class="province-grid">${ps.map(provinceCard).join('')}</div></section>`:''}).join('')}
const detailOriginal=detail;
detail=function(id){let html=detailOriginal(id);const t=tours.find(t=>t.id===id&&!t.hidden);if(!t)return html;const doc=new DOMParser().parseFromString(html,'text/html'),tabs=doc.querySelector('.tabs'),it=doc.querySelector('#itinerary'),layout=doc.querySelector('.detail-layout');tabs.prepend(tabs.lastElementChild);layout.firstElementChild.prepend(it);doc.querySelector('.breadcrumb').innerHTML=`<a href="#tours">Lữ trình</a> / <a href="#province/${province(t.province).id}">${esc(t.province)}</a>`;doc.querySelector('#overview').insertAdjacentHTML('beforeend',`<h3>Bao gồm</h3><p>${esc(t.includes||'Di chuyển theo lịch trình, lưu trú và hướng dẫn viên tại điểm đến.')}</p><h3>Không bao gồm</h3><p>${esc(t.excludes||'Vé máy bay đến điểm đón, ăn uống tự túc và chi phí cá nhân.')}</p><h3>Điểm đón</h3><p>${esc(t.pickup||'Điểm hẹn tại trung tâm '+t.province+'; xác nhận địa chỉ cụ thể cùng nhân viên trước khi đặt.')}</p><h3>Chính sách hủy</h3><p>Đơn chờ xác nhận và chưa thanh toán có thể hủy tại Hành trình của tôi. Đơn đã xác nhận cần liên hệ quản trị viên; đơn đã thu tiền cần được ghi nhận hoàn tiền trước khi hủy.</p>`);doc.querySelector('.detail-photo').insertAdjacentHTML('afterend',`<div class="tour-gallery">${province(t.province).attractions.map(n=>`<button type="button" onclick="document.querySelector('.detail-photo img').src=this.querySelector('img').src;document.querySelector('.detail-photo img').alt=this.querySelector('img').alt">${photo(n)}</button>`).join('')}</div>`);doc.querySelector('.wrap').insertAdjacentHTML('beforeend',`<section class="detail-section"><h2>Hành trình bạn có thể thích</h2><div class="grid">${tours.filter(x=>!x.hidden&&x.id!==id&&province(x.province).region===province(t.province).region).slice(0,3).map(card).join('')}</div></section>`);return doc.body.innerHTML;};
const renderOriginal=render;
render=function(){renderOriginal();if(location.hash.startsWith('#places'))$('#province-list').classList.remove('province-grid');document.querySelectorAll('.tabs a').forEach((a,i)=>{a.classList.toggle('active',i===0);a.addEventListener('click',()=>{document.querySelectorAll('.tabs a').forEach(x=>x.classList.remove('active'));a.classList.add('active')})});if(window.tourObserver)window.tourObserver.disconnect();window.tourObserver=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){document.querySelectorAll('.tabs a').forEach(a=>a.classList.toggle('active',a.getAttribute('onclick').includes("'#"+e.target.id+"'"))) }},{rootMargin:'-140px 0px -55% 0px'});document.querySelectorAll('.detail-layout .detail-section[id]').forEach(s=>window.tourObserver.observe(s));};
render();
const filterToursBase=filterTours;let visibleTours=12;
filterTours=function(more=false){if(!more)visibleTours=12;filterToursBase();const cards=[...document.querySelectorAll('#results .tour-card')];cards.forEach((c,i)=>c.hidden=i>=visibleTours);document.getElementById('more-tours')?.remove();if(cards.length>visibleTours){const b=document.createElement('button');b.id='more-tours';b.textContent='Xem thêm hành trình';b.onclick=()=>{visibleTours+=12;filterTours(true)};$('#results').after(b)}};
const detailWithContent=detail;
detail=function(id){const doc=new DOMParser().parseFromString(detailWithContent(id),'text/html');const t=tours.find(t=>t.id===id);if(!t||!doc.querySelector('#people'))return doc.body.innerHTML;doc.querySelector('#people').parentElement.outerHTML=`<label>Người lớn<div class="stepper"><button type="button" onclick="stepGuests('people',-1,'${esc(id)}')">−</button><input type="number" id="people" min="1" value="1" required oninput="quote('${esc(id)}')"><button type="button" onclick="stepGuests('people',1,'${esc(id)}')">+</button></div></label><label>Trẻ em<div class="stepper"><button type="button" onclick="stepGuests('children',-1,'${esc(id)}')">−</button><input type="number" id="children" min="0" value="0" required oninput="quote('${esc(id)}')"><button type="button" onclick="stepGuests('children',1,'${esc(id)}')">+</button></div></label><p class="notice">Giá trẻ em bằng giá người lớn trong bản trải nghiệm. Mỗi khách sử dụng một chỗ.</p>`;return doc.body.innerHTML};
function stepGuests(field,delta,id){const input=document.getElementById(field);input.value=Math.max(field==='people'?1:0,(+input.value||0)+delta);quote(id)}
quote=function(id){const t=tours.find(t=>t.id===id),total=(+$('#people').value||0)+(+$('#children')?.value||0),available=Math.max(0,remaining(t,$('#departure').value));$('#quote').textContent=money(t.price*total);const button=$('.booking-panel form button:not([type="button"])');if(button){button.disabled=total>available;button.textContent=total>available?'Chỉ còn '+available+' chỗ':'Đặt tour →'}};
book=function(e,id){e.preventDefault();if(!user){account();toast('Vui lòng đăng nhập để đặt tour.');return}if(user.role==='admin')return toast('Vui lòng dùng tài khoản khách hàng để đặt tour.');const t=tours.find(t=>t.id===id),adults=+$('#people').value,children=+$('#children').value,n=adults+children,d=$('#departure').value;if(!Number.isInteger(adults)||adults<1||!Number.isInteger(children)||children<0||n>remaining(t,d))return toast('Vui lòng kiểm tra số khách và số chỗ còn lại.');const f=new FormData(e.target),b={id:'MG'+crypto.randomUUID().slice(0,8).toUpperCase(),tourId:id,title:t.title,date:d,people:n,adults,children,unitPrice:t.price,total:n*t.price,name:f.get('name'),phone:f.get('phone'),userId:user.id,status:'pending',paid:false};bookings.unshift(b);save();location.hash='bookings';modal(`<h2>Đặt tour thành công</h2><p>Mã đơn: <strong>${esc(b.id)}</strong></p><h3>${esc(b.title)}</h3><p>${date(d)} · ${adults} người lớn · ${children} trẻ em</p><p>Tổng tiền: ${money(b.total)}</p><p>Đơn đang chờ xác nhận.</p><button onclick="document.querySelector('dialog').close()">Xem hành trình của tôi</button>`)};
render();

function tourType(t){if(t.category)return t.category;return /biển|vịnh|đảo|phú quốc|cát bà|hạ long/i.test(t.title+' '+t.place)?'Biển đảo':/núi|đèo|sa pa|đà lạt|fansipan|bản |mây/i.test(t.title+' '+t.place)?'Núi & thiên nhiên':'Văn hóa & khám phá'}
const baseCard=card;card=function(t){return baseCard(t).replace('<p class="sub">','<p class="tour-type">'+esc(tourType(t))+'</p><p class="sub">')};
const basePhoto=photo;photo=function(name){const t=tours.find(t=>t.place===name&&t.cover);return t?`<img src="${esc(t.cover)}" alt="${esc(name)}" loading="lazy">`:basePhoto(name)};
function bookingDetail(id){const b=bookings.find(b=>b.id===id&&(user?.role==='admin'||b.userId===user?.id));if(!b)return;modal(`<h2>Đơn ${esc(b.id)}</h2><h3>${esc(b.title)}</h3><p>Khởi hành: ${date(b.date)}</p><p>${b.adults??b.people} người lớn · ${b.children||0} trẻ em</p><p>Liên hệ: ${esc(b.name)} · ${esc(b.phone)}</p><p>${statusName[b.status]} · ${b.paid?'Đã thanh toán':'Chưa thanh toán'}</p><p>Tổng tiền: <strong>${money(b.total)}</strong></p><a class="textlink" href="#tour/${esc(b.tourId)}" onclick="document.querySelector('dialog').close()">Xem tour →</a>`)}
const baseBookings=myBookings;myBookings=function(){return baseBookings().replace(/<small>(MG[A-Z0-9]+|DV[0-9]+) ·/g,(m,id)=>`<button class="outline" onclick="bookingDetail('${id}')">Chi tiết đơn</button><small>${id} ·`)};
const baseDetailed=detail;detail=function(id){const t=tours.find(t=>t.id===id),doc=new DOMParser().parseFromString(baseDetailed(id),'text/html');if(t?.itinerary?.length&&doc.querySelector('#itinerary')){doc.querySelector('#itinerary').innerHTML='<h2>Lịch trình dự kiến</h2>'+t.itinerary.map((text,i)=>`<div class="day"><strong>NGÀY ${i+1}</strong><p>${esc(text)}</p></div>`).join('')}return doc.body.innerHTML};
function photoCredits(){const names=[...new Set(Object.values(IMAGE_MAP).map(x=>x.source))].sort();modal('<h2>Nguồn ảnh</h2><p>Ảnh địa danh, đặc sản trong website được tổng hợp từ các nguồn dưới đây.</p>'+names.map(n=>'<p>'+esc(n)+'</p>').join('')+'<p>Ảnh tour do quản trị viên tải lên: người tải lên cung cấp và chịu trách nhiệm ghi nguồn.</p>')}
const creditButton=document.createElement('button');creditButton.className='outline';creditButton.textContent='Nguồn ảnh';creditButton.onclick=photoCredits;document.querySelector('footer').append(creditButton);
render();
